// Every command exposed by the plugin. `tauri_plugin::Builder` generates the
// `allow-*`/`deny-*` permissions for them under `permissions/autogenerated/`.
const COMMANDS: &[&str] = &[
    "chessin_ping",
    "cbh_to_pgn",
    "store_get",
    "store_set",
    "store_delete",
    "doc_put",
    "doc_get",
    "doc_list",
    "doc_delete",
    "doc_versions",
    "doc_restore_version",
    "move_to_trash",
    "scan_chessbase",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
}
